import java.util.*;

class Solution {
    public int openLock(String[] deadends, String target) {
        Set<String> dead = new HashSet<>(Arrays.asList(deadends));
        if (dead.contains("0000")) return -1;

        Set<String> visited = new HashSet<>();
        Deque<String> queue = new ArrayDeque<>();
        visited.add("0000");
        queue.add("0000");
        int steps = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int k = 0; k < size; k++) {
                String cur = queue.poll();
                if (cur.equals(target)) return steps;

                for (int i = 0; i < 4; i++) {
                    int d = cur.charAt(i) - 48;
                    for (int delta : new int[]{1, 9}) {
                        int nd = (d + delta) % 10;
                        String next = cur.substring(0, i) + nd + cur.substring(i + 1);
                        if (dead.contains(next) || !visited.add(next)) continue;
                        queue.add(next);
                    }
                }
            }
            steps++;
        }
        return -1;
    }
}

import java.util.*;

class Solution {
    private static final int[] POW = {1000, 100, 10, 1};

    public int openLock(String[] deadends, String target) {
        int[] state = new int[10000];
        for (String d : deadends) state[Integer.parseInt(d)] = 2;
        if (state[0] == 2) return -1;

        int goal = Integer.parseInt(target);
        Deque<Integer> queue = new ArrayDeque<>();
        state[0] = 1;
        queue.add(0);
        int steps = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int k = 0; k < size; k++) {
                int cur = queue.poll();
                if (cur == goal) return steps;

                for (int pos = 0; pos < 4; pos++) {
                    for (int dir = -1; dir <= 1; dir += 2) {
                        int next = turn(cur, pos, dir);
                        if (state[next] != 0) continue;
                        state[next] = 1;
                        queue.add(next);
                    }
                }
            }
            steps++;
        }
        return -1;
    }

    private int turn(int s, int pos, int dir) {
        int w = POW[pos];
        int d = (s / w) % 10;
        int nd = (d + dir + 10) % 10;
        return s + (nd - d) * w;
    }
}

import java.util.*;

class Solution {
    private static final int[] POW = {1000, 100, 10, 1};

    public int openLock(String[] deadends, String target) {
        boolean[] dead = new boolean[10000];
        for (String d : deadends) dead[Integer.parseInt(d)] = true;

        int goal = Integer.parseInt(target);
        if (dead[0] || dead[goal]) return -1;
        if (goal == 0) return 0;

        int[] distA = new int[10000];
        int[] distB = new int[10000];
        Arrays.fill(distA, -1);
        Arrays.fill(distB, -1);
        distA[0] = 0;
        distB[goal] = 0;

        List<Integer> frontA = new ArrayList<>();
        List<Integer> frontB = new ArrayList<>();
        frontA.add(0);
        frontB.add(goal);

        while (!frontA.isEmpty() && !frontB.isEmpty()) {
            boolean fromA = frontA.size() <= frontB.size();
            List<Integer> front = fromA ? frontA : frontB;
            int[] myDist = fromA ? distA : distB;
            int[] otherDist = fromA ? distB : distA;

            List<Integer> next = new ArrayList<>();
            for (int s : front) {
                for (int pos = 0; pos < 4; pos++) {
                    for (int dir = -1; dir <= 1; dir += 2) {
                        int nb = turn(s, pos, dir);
                        if (dead[nb] || myDist[nb] != -1) continue;
                        myDist[nb] = myDist[s] + 1;
                        if (otherDist[nb] != -1) return myDist[nb] + otherDist[nb];
                        next.add(nb);
                    }
                }
            }
            if (fromA) frontA = next;
            else frontB = next;
        }
        return -1;
    }

    private int turn(int s, int pos, int dir) {
        int w = POW[pos];
        int d = (s / w) % 10;
        int nd = (d + dir + 10) % 10;
        return s + (nd - d) * w;
    }
}
